fn solve(input: Vec<char>) -> Vec<char> {
    // Get the first two characters (guaranteed to exist and be digits)
    let first_char = input[0];
    let second_char = input[1];
    
    // Helper function to map digit char to good count
    fn good_count(digit: char) -> u8 {
        match digit {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => unreachable!(), // According to problem, first two chars are digits
        }
    }
    
    // Calculate product
    let product = good_count(first_char) as u32 * good_count(second_char) as u32;
    
    // Convert to string and then to Vec<char>
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}